// 🚀 ETL CBA — PADRÃO PRODUÇÃO

// 🔤 normalização
const normalize = str =>
  str
    ? str.toString().normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim()
    : '';

// 🧹 limpeza básica
const limpar = v =>
  v !== null && v !== undefined ? v.toString().trim() : '';

// 🔥 evita notação científica
const safe = v => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number') return v.toFixed(0);
  return v.toString();
};

// ✅ CPF — 11 dígitos com zeros à esquerda, forçando texto no Excel
const formatarCPF = valor => {
  if (!valor) return '="00000000000"';
  const num = valor.toString().replace(/\D/g, '').trim();
  const cpfFormatado = num.padStart(11, '0').slice(-11);
  return `="${cpfFormatado}"`;
};

// 📮 CEP
const formatarCEP = v => {
  let num = safe(v).replace(/\D/g,'');
  return num.padStart(8,'0').slice(0,8);
};

// 📞 TELEFONE (remove tudo + detecta múltiplos)
const formatarTelefones = v => {

  if (!v) return { tel1: '', tel2: '' };

  // quebra possíveis múltiplos
  const partes = v.toString().split(/[\/|,;]/);

  const limparNumero = num =>
    num.replace(/\D/g,'');

  const nums = partes.map(p => limparNumero(p)).filter(n => n.length >= 8);

  return {
    tel1: nums[0] || '',
    tel2: nums[1] || ''
  };
};

// 📅 DATA → AAAAMMDD
const formatarData = v => {

  if (!v) return '';

  const s = v.toString().trim();

  if (/^\d{8}$/.test(s)) return s;

  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)) {
    const [d,m,a] = s.split('/');
    return `${a}${m.padStart(2,'0')}${d.padStart(2,'0')}`;
  }

  return '';
};



// 💰 Valor — duas casas decimais com vírgula, forçando texto no Excel
const formatarValor = valor => {
  if (valor === undefined || valor === null || valor === '') return '="0,00"';
  let numStr = valor.toString().replace(/[^\d,.-]/g, '').trim();
  numStr = numStr.replace(',', '.');
  const num = parseFloat(numStr);
  if (isNaN(num)) return '="0,00"';
  return `="${num.toFixed(2).replace('.', ',')}"`;
};

// 🏠 ENDEREÇO
const formatarEndereco = v =>
  v ? v.toString().replace(/[.,;:]/g,'').trim() : '';

// 📥 leitura (CBA já vem do node anterior)
let inputData = $input.all().map(i => i.json);

// 🧭 headers dinâmicos
const headers = {};
if (inputData.length) {
  Object.keys(inputData[0]).forEach(k => {
    headers[normalize(k)] = k;
  });
}

// 🔍 getValue
const getValue = (row, col) => {
  const key = headers[normalize(col)];
  return key ? row[key] : '';
};

// 🧱 processamento
const output = inputData.map(row => {

  // 📞 trata telefone + celular juntos
  const telRaw = getValue(row,'TELEFONE') || getValue(row,'CELULAR');
  const tels = formatarTelefones(telRaw);

  return {
    json: {


      'MATRÍCULA': getValue(row,'MATRÍCULA'),

      'NOME': getValue(row,'NOME'),

      'CURSO': getValue(row,'CURSO'),

      'CPF': formatarCPF(getValue(row,'CPF')),

      'NASC': formatarData(getValue(row,'NASC')),

      'ENDERECO': formatarEndereco(getValue(row,'ENDERECO')),

      'BAIRRO': getValue(row,'BAIRRO'),

      'CIDADE': getValue(row,'CIDADE'),

      'CEP': formatarCEP(getValue(row,'CEP')),

      'ESTADO': getValue(row,'ESTADO'),

      'TELEFONE': tels.tel1,

      'CELULAR': tels.tel2,

      'REFERENCIA': getValue(row,'REFERENCIA'),

      'DATA PARCELA': formatarData(getValue(row,'DATA PARCELA')),

      'VALOR PARCEL': formatarValor(getValue(row,'VALOR PARCEL')),

      'RESPONSAVEL': getValue(row,'RESPONSAVEL'),

      'CPF RESPONSAVEL': formatarCPF(getValue(row,'CPF RESPONSAVEL')),

      'RESPONSAVEL NASCIMENTO': formatarData(getValue(row,'NASC')),

      'RESPONSAVEL ENDERECO': formatarEndereco(getValue(row,'ENDERECO')),

      'RESPONSAVEL BAIRRO': getValue(row,'BAIRRO'),

      'RESPONSAVEL CIDADE': getValue(row,'CIDADE'),

      'RESPONSAVEL CEP': formatarCEP(getValue(row,'CEP')),

      'RESPONSAVEL ESTADO': getValue(row,'ESTADO'),

      'RESPONSAVEL TELEFONE': tels.tel1,

      'RESPONSAVEL CELULAR': tels.tel2,

      'RESPONSAVEL EMAIL': getValue(row,'E-MAIL'),

      'DADOS ESPECIFICOS CLIENT': getValue(row,'VALOR'),

      'VALOR PARCELA2 (BOLSA)': getValue(row,'VALOR')

    }
  };

});

// remove linhas vazias
return output.filter(item =>
  Object.values(item.json).some(v => v && v.toString().trim() !== '')
);
